1	<!DOCTYPE html>
2	<html lang="vi">
3	<head>
4	<meta charset="utf-8">
5	<title>Bản dựng thử: cây và người đi bộ</title>
6	<style>
7	  html, body { margin: 0; height: 100%; overflow: hidden; background: #bfdcf0; font-family: system-ui, "Segoe UI", sans-serif; }
8	  canvas { display: block; }
9	  .bar { position: fixed; left: 12px; top: 12px; display: flex; gap: 6px; flex-wrap: wrap; max-width: 70vw; }
10	  .bar button { border: 0; border-radius: 8px; padding: 8px 12px; font-size: 14px; background: rgba(20, 30, 40, .78); color: #fff; cursor: pointer; }
11	  .bar button:hover { background: rgba(20, 30, 40, .95); }
12	  .note { position: fixed; left: 12px; bottom: 12px; max-width: 520px; padding: 10px 12px; border-radius: 8px; background: rgba(20, 30, 40, .78); color: #fff; font-size: 13px; line-height: 1.45; }
13	  .tag { position: fixed; transform: translate(-50%, -50%); padding: 4px 10px; border-radius: 6px; font-weight: 700; font-size: 14px; color: #fff; pointer-events: none; white-space: nowrap; }
14	  #tagOld { background: rgba(120, 60, 50, .85); }
15	  #tagNew { background: rgba(30, 110, 60, .9); }
16	</style>
17	</head>
18	<body>
19	<div class="bar">
20	  <button data-v="all">Toàn cảnh</button>
21	  <button data-v="tree">Cây bóng mát</button>
22	  <button data-v="palm">Cây dừa</button>
23	  <button data-v="people">Người đi bộ</button>
24	  <button data-v="run">Bám theo người chạy bộ</button>
25	  <button data-v="old">Hiện tại (để so)</button>
26	</div>
27	<div id="tagOld" class="tag">HIỆN TẠI</div>
28	<div id="tagNew" class="tag">ĐỀ XUẤT</div>
29	<div class="note">Bản dựng thử, chỉ để xem dáng. Kéo chuột để xoay, lăn chuột để phóng to/thu nhỏ.<br>
30	Bên trái là cây và người như đang có trong demo, bên phải là đề xuất: cây bóng mát, cây dừa, người có tay chân bước đi, người chạy bộ, người đứng lan can ngắm sông / chụp ảnh, nón lá, ba lô, trẻ em đi cùng người lớn.</div>
31	
32	<script type="module">
33	import * as THREE from './three.module.min.js';
34	
35	/* ---------- tiện ích ---------- */
36	function rng(seed) { let a = seed >>> 0; return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
37	function merge(list) {
38	  const gs = list.map(g => g.index ? g.toNonIndexed() : g), out = new THREE.BufferGeometry();
39	  for (const name of Object.keys(gs[0].attributes)) {
40	    const size = gs[0].attributes[name].itemSize; let n = 0; gs.forEach(g => n += g.attributes[name].count);

170	  [a, b, c].forEach(m => { m.castShadow = true; m.receiveShadow = true; });
171	  b.customDepthMaterial = new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking, map: matFrond.map, alphaTest: 0.4 });
172	  g.add(a, b, c); return g;
173	}
174	
175	/* ---------- ĐỀ XUẤT: người đi bộ (1 InstancedMesh, tay chân vung trong vertex shader) ---------- */
176	const SKIN = hex(0xe2b48c), HAIR = hex(0x1c1612), HAT = hex(0xe9dcae), PACK = hex(0x7a2f2a);
177	function tag(g, part, pivot, fix, maskFn, seg = 0, pivot2 = 0) {
178	  const n = g.attributes.position.count, P = new Float32Array(n).fill(part), V = new Float32Array(n).fill(pivot), M = new Float32Array(n), F = new Float32Array(n * 3);
179	  for (let i = 0; i < n; i++) { M[i] = maskFn ? maskFn(g.attributes.position.getY(i)) : 0; F.set(fix, i * 3); }
180	  g.setAttribute('aPart', new THREE.BufferAttribute(P, 1)); g.setAttribute('aPivot', new THREE.BufferAttribute(V, 1)); g.setAttribute('aMask', new THREE.BufferAttribute(M, 1)); g.setAttribute('aFix', new THREE.BufferAttribute(F, 3));
181	  g.setAttribute('aSeg', new THREE.BufferAttribute(new Float32Array(n).fill(seg), 1)); g.setAttribute('aPivot2', new THREE.BufferAttribute(new Float32Array(n).fill(pivot2), 1));
182	  return g.index ? g.toNonIndexed() : g;
183	}
184	const SHOE = hex(0x2a2a2e);
185	function personGeo() {
186	  const shirt = () => 1, pants = () => 2, cap = (r, l) => new THREE.CapsuleGeometry(r, l, 3, 7), HIP = 0.86, KNEE = 0.46, SHO = 1.37, ELB = 1.1, parts = [
187	    tag(cap(0.15, 0.3).scale(0.78, 1, 1.18).translate(0, 1.12, 0), 0, 0, SKIN, shirt),          // thân
188	    tag(new THREE.SphereGeometry(0.115, 10, 8).translate(0, 1.54, 0), 0, 0, SKIN),              // đầu
189	    tag(new THREE.SphereGeometry(0.123, 10, 6, 0, 6.3, 0, 1.75).translate(-0.018, 1.553, 0), 0, 0, HAIR), // tóc
190	    tag(new THREE.ConeGeometry(0.31, 0.17, 12).translate(0, 1.7, 0), 5, 0, HAT),                // nón lá
191	    tag(new THREE.BoxGeometry(0.13, 0.32, 0.25).translate(-0.18, 1.17, 0), 6, 0, PACK),         // ba lô
192	  ];
193	  for (const [side, leg, arm] of [[1, 1, 3], [-1, 2, 4]]) {
194	    parts.push(tag(cap(0.072, 0.28).translate(0, 0.66, side * 0.085), leg, HIP, SKIN, pants));                       // đùi
195	    parts.push(tag(cap(0.058, 0.3).translate(0, 0.25, side * 0.085), leg, HIP, SKIN, pants, 1, KNEE));               // ống chân
196	    parts.push(tag(new THREE.BoxGeometry(0.23, 0.07, 0.095).translate(0.045, 0.035, side * 0.085), leg, HIP, SHOE, null, 1, KNEE)); // giày
197	    parts.push(tag(cap(0.05, 0.18).translate(0, 1.235, side * 0.225), arm, SHO, SKIN, shirt));                       // bắp tay (áo cộc tay)
198	    parts.push(tag(cap(0.042, 0.2).translate(0, 0.96, side * 0.225), arm, SHO, SKIN, null, 1, ELB));                 // cẳng tay
199	  }
200	  return merge(parts);
201	}
202	const uT = { value: 0 };
203	function patchPerson(mat, withColor) {
204	  mat.onBeforeCompile = (sh) => {
205	    sh.uniforms.uT = uT;
206	    sh.vertexShader = sh.vertexShader
207	      .replace('#include <common>', `#include <common>
208	        attribute float aPart; attribute float aPivot; attribute float aMask; attribute vec3 aFix; attribute vec4 aVar; attribute vec3 aPants; attribute float aSeg; attribute float aPivot2; uniform float uT;
209	        float pFlag(float b) { return mod(floor(aVar.z / b), 2.0); }
210	        // x: góc khớp gốc (hông / vai), y: góc khớp giữa (gối / khuỷu). Dương = đưa về phía trước.
211	        vec2 pAngles() {
212	          float A = aVar.y, ph = uT * aVar.w + aVar.x, run = smoothstep(0.42, 0.6, A);
213	          if (aPart > 0.5 && aPart < 2.5) { float f = aPart < 1.5 ? ph : ph + 3.14159;
214	            float sw = max(0.0, cos(f - 0.35)), sr = max(0.0, cos(f + 0.45));   // gập gối khi đưa chân lên trước; chạy: gập sớm và sâu hơn
215	            return vec2(A * sin(f) + mix(0.12 * A, 0.22, run), -mix(A * 2.0 * sw * sw + 0.06 * step(0.01, A), 0.38 + 1.5 * sr * sr, run)); }
216	          if (aPart > 2.5 && aPart < 4.5) { float f = aPart < 3.5 ? ph + 3.14159 : ph;
217	            if (aPart > 3.5 && pFlag(4.0) > 0.5) return vec2(1.0, 1.05);             // giơ tay chụp ảnh
218	            return vec2(A * (0.65 + run * 0.5) * sin(f) - 0.05, 0.16 + run * 1.25 + A * 0.35 * max(0.0, sin(f))); }
219	          return vec2(0.0);
220	        }
221	        vec2 pRot(vec2 p, float a) { float c = cos(a), s = sin(a); return vec2(p.x * c - p.y * s, p.x * s + p.y * c); }`)
222	      .replace('#include <begin_vertex>', `#include <begin_vertex>
223	        vec2 pa = pAngles();
224	        if (aSeg > 0.5) transformed.xy = pRot(transformed.xy - vec2(0.0, aPivot2), pa.y) + vec2(0.0, aPivot2);
225	        transformed.xy = pRot(transformed.xy - vec2(0.0, aPivot), pa.x) + vec2(0.0, aPivot);
226	        float pRun = smoothstep(0.42, 0.6, aVar.y);
227	        if (aPart < 0.5 || aPart > 2.5) transformed.xy = pRot(transformed.xy - vec2(0.0, 0.86), -0.17 * pRun) + vec2(0.0, 0.86);   // chạy: thân đổ về trước
228	        if (aPart > 4.5 && aPart < 5.5 && pFlag(1.0) < 0.5) transformed *= 0.0;
229	        if (aPart > 5.5 && pFlag(2.0) < 0.5) transformed *= 0.0;
230	        float pph = uT * aVar.w + aVar.x;
231	        transformed.y += mix(0.022 * cos(2.0 * pph) - 0.022, 0.075 * (0.5 - 0.5 * cos(2.0 * pph)), pRun) * step(0.01, aVar.y);   // đi: thấp nhất khi hai chân dang rộng; chạy: bật lên giữa hai bước
232	        transformed.z += 0.018 * sin(pph) * step(0.01, aVar.y) * smoothstep(0.3, 1.6, transformed.y);                            // lắc vai nhẹ sang hai bên`);
233	    if (withColor) sh.vertexShader = sh.vertexShader
234	      .replace('#include <beginnormal_vertex>', '#include <beginnormal_vertex>\n vec2 pn = pAngles(); objectNormal.xy = pRot(objectNormal.xy, pn.x + (aSeg > 0.5 ? pn.y : 0.0));')
235	      .replace('#include <color_vertex>', 'vColor = aMask < 0.5 ? aFix : (aMask < 1.5 ? instanceColor : aPants);');
236	  };
237	  return mat;
238	}
239	const SHIRTS = [0xd94b3d, 0x2f6fb5, 0xf2f2ee, 0x3a3a3a, 0xe0b23a, 0x4f9a5a, 0xc76fa8, 0xf08a4b, 0x7fc4d9, 0xffffff], PANTS = [0x26324a, 0x1d1d1f, 0x6b6f76, 0xc9b999, 0x3d5a80, 0x4a3b32];
240	const walkers = [];
241	{
242	  const r = rng(77), X0 = 3, X1 = 50;
243	  const add = (o) => walkers.push(Object.assign({ x: X0 + r() * (X1 - X0), z: r() * 5 - 0.5, dir: r() < 0.5 ? -1 : 1, speed: 1.05 + r() * 0.3, amp: 0.34, flags: 0, s: 0.94 + r() * 0.14, lo: X0, hi: X1, phase: r() * 6.3 }, o));
244	  for (let i = 0; i < 9; i++) add({ flags: (r() < 0.25 ? 1 : 0) + (r() < 0.25 ? 2 : 0) });
245	  for (let i = 0; i < 3; i++) { const x = X0 + r() * (X1 - X0), z = r() * 4, dir = r() < 0.5 ? -1 : 1, speed = 1.05 + r() * 0.2; add({ x, z, dir, speed }); add({ x: x + 0.15, z: z + 0.62, dir, speed, flags: i === 0 ? 1 : 0 }); }   // đi đôi
246	  { const x = 20, z = 1.2, dir = 1, speed = 0.85; add({ x, z, dir, speed }); add({ x: x + 0.1, z: z + 0.5, dir, speed, s: 0.6 }); }                                                             // người lớn + trẻ em
247	  for (let i = 0; i < 4; i++) add({ speed: 2.6 + r() * 0.4, amp: 0.6, run: 1, z: 3.5 + r() * 1.2 });                                                                                                   // chạy bộ
248	  for (let i = 0; i < 6; i++) add({ x: 8 + i * 6.5 + r() * 3, z: 5.75, speed: 0, amp: 0, stand: true, flags: (i % 3 === 0 ? 4 : 0) + (i % 4 === 1 ? 2 : 0) + (i === 4 ? 1 : 0) });             // đứng lan can, vài người chụp ảnh
249	}
250	const pGeo = personGeo(), pMat = patchPerson(new THREE.MeshStandardMaterial({ roughness: 0.85 }), true);
251	const people = new THREE.InstancedMesh(pGeo, pMat, walkers.length);
252	{
253	  const r = rng(9), V = new Float32Array(walkers.length * 4), Pn = new Float32Array(walkers.length * 3), c = new THREE.Color();
254	  walkers.forEach((w, i) => { V.set([w.phase, w.amp, w.flags, w.run ? 8.8 / Math.sqrt(w.s) : w.amp ? 6.2832 * w.speed / (4 * 0.86 * w.s * Math.sin(w.amp) * (w.run || 1)) : 0], i * 4); people.setColorAt(i, c.setHex(SHIRTS[Math.floor(r() * SHIRTS.length)])); c.setHex(PANTS[Math.floor(r() * PANTS.length)]); Pn.set([c.r, c.g, c.b], i * 3); });
255	  pGeo.setAttribute('aVar', new THREE.InstancedBufferAttribute(V, 4)); pGeo.setAttribute('aPants', new THREE.InstancedBufferAttribute(Pn, 3));
256	}
257	people.customDepthMaterial = patchPerson(new THREE.MeshDepthMaterial({ depthPacking: THREE.RGBADepthPacking }), false);
258	people.castShadow = true; people.frustumCulled = false; scene.add(people);
259	
260	/* ---------- HIỆN TẠI: cây cầu + nón, người ống trụ ---------- */
261	const oldWalkers = [];
262	{
263	  const trunkM = new THREE.MeshStandardMaterial({ color: 0x6b5238, roughness: 1 });
264	  const round = (x, z, h, rr, hue) => {
265	    const t = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.35, h, 6).translate(0, h / 2, 0), trunkM);
266	    const c = new THREE.Mesh(new THREE.SphereGeometry(1, 10, 8), new THREE.MeshStandardMaterial({ color: new THREE.Color().setHSL(hue, 0.45, 0.4), roughness: 0.9 }));
267	    c.scale.set(rr, rr * 0.85, rr); c.position.y = h + rr * 0.6; const g = new THREE.Group(); g.add(t, c); g.position.set(x, 0, z); t.castShadow = c.castShadow = true; scene.add(g);
268	  };
269	  const palm = (x, z, h) => {
270	    const t = new THREE.Mesh(new THREE.CylinderGeometry(0.22 * 0.8, 0.35 * 0.8, h, 6).translate(0, h / 2, 0), trunkM);
271	    const c = new THREE.Mesh(new THREE.ConeGeometry(1, 1, 9, 1, true), new THREE.MeshStandardMaterial({ color: 0x4f8f3a, roughness: 0.85, side: THREE.DoubleSide }));
272	    c.scale.set(3.8, 1.6, 3.8); c.position.y = h + 0.3; const g = new THREE.Group(); g.add(t, c); g.position.set(x, 0, z); t.castShadow = c.castShadow = true; scene.add(g);
273	  };
274	  round(-12, -6, 4.2, 3.2, 0.29); palm(-24, -6, 10); round(-36, -6, 5, 3.8, 0.31);
275	  const body = merge([new THREE.CylinderGeometry(0.19, 0.24, 1.25, 7).translate(0, 0.63, 0), new THREE.SphereGeometry(0.13, 8, 6).translate(0, 1.42, 0)].map(g => { g.deleteAttribute('uv'); return g; }));
276	  const r = rng(4);
277	  for (let i = 0; i < 12; i++) {
278	    const m = new THREE.Mesh(body, new THREE.MeshStandardMaterial({ color: SHIRTS[Math.floor(r() * 7)], roughness: 0.85 })); m.castShadow = true; scene.add(m);
279	    oldWalkers.push({ m, x: -42 + r() * 38, z: r() * 5, dir: r() < 0.5 ? -1 : 1, speed: 1 + r() * 0.6, i });
280	  }
281	}
282	
283	/* ---------- đặt cây đề xuất ---------- */
284	const place = (g, x, z, s, ry) => { g.position.set(x, 0, z); g.scale.setScalar(s); g.rotation.y = ry; scene.add(g); };
285	place(shadeTree(21), 12, -6, 1.0, 0.3); place(shadeTree(57), 40, -7, 1.12, 2.1);
286	place(coconutPalm(8), 25, -5, 1, 0.4); place(coconutPalm(31), 31, -9, 1.1, 2.6); place(coconutPalm(64), 51, -5, 0.95, 4.2);
287	
288	/* ---------- camera xoay bằng chuột ---------- */
289	const VIEWS = { all: [[4, 4, -2], 62, 0.0, 1.22], tree: [[12, 4.5, -6], 26, 0.25, 1.38], palm: [[27, 6, -6], 26, -0.2, 1.42], people: [[22, 1.0, 3], 8, 0.5, 1.4], old: [[-24, 4, -3], 34, 0.0, 1.3], run: [[22, 0.95, 4], 5.5, 0.55, 1.42] };
290	let follow = -1;
291	const orbit = { t: new THREE.Vector3(), d: 60, yaw: 0, pol: 1.2 };
292	const setView = (k) => { const v = VIEWS[k]; follow = k === "run" ? walkers.findIndex(w => w.run) : -1; orbit.t.set(...v[0]); orbit.d = v[1]; orbit.yaw = v[2]; orbit.pol = v[3]; };
